#!/usr/bin/env node
/**
 * DERIVE the desk's parameters instead of asserting them.
 *
 *   node scripts/derive-parameters.mjs
 *
 * Why this file exists: an earlier version of lib/strategy.mjs carried numbers I had
 * simply chosen (25 WETH, 200 trades, a 4% vol floor) and then TUNED against synthetic
 * data generated by the same author. Tuning on your own simulation is circular and is
 * how a strategy ends up fitted to a fiction. Everything below is either
 *
 *   [MEASURED]  read from Robinhood Chain, reproducible with npm run verify
 *   [DERIVED]   algebra from a measured input, shown in full
 *   [CHOICE]    a preference that cannot be derived, stated with its consequence
 *
 * Standard references for the model, none of which are novel here:
 *   Ho & Stoll (1981), "Optimal dealer pricing under transactions and return uncertainty"
 *   Avellaneda & Stoikov (2008), "High-frequency trading in a limit order book"
 *   Grossman & Miller (1988), "Liquidity and market structure"
 * The Avellaneda-Stoikov result used here is the inventory-risk term gamma*sigma^2*q,
 * which says a maker's tolerable inventory falls with the SQUARE of volatility.
 */

const line = (s = "") => console.log(s);
const rule = (c = "-") => line(c.repeat(78));

/* ============================== MEASURED INPUTS ============================== */
const M = {
  hookFee: 0.05,          // Hook.FEE_BPS() = 500, verified on chain
  gasUsd: 0.033,          // 209k gas @ 0.057 gwei, ETH ~$2,735, from 8 real txs
  poolDepthWeth: 111.8,   // full-range virtual reserve at current price
  hourlyVolNow: 0.0149,   // realised, last 24h
  volume24hWeth: 13.7,    // from the hook's own FeeCollected events
  trades24h: 146,
  bookUsd: 86,            // Hunt's actual idle rewards
  ethUsd: 2734.86,
};

line("THE BANK OF FRIENDS :: parameter derivation");
line(`run ${new Date().toISOString()}`);
line();
line("MEASURED INPUTS (npm run verify re-checks every one of these)");
rule();
for (const [k, v] of Object.entries(M)) line(`  ${k.padEnd(18)} ${v}`);
line();

/* ===================== 1. MINIMUM GRID STEP  [DERIVED] ====================== */
line("1. MINIMUM GRID STEP  [DERIVED]");
rule();
line("  Buy with W WETH at price p, receive W(1-f)/p in RF.");
line("  Sell that RF at p(1+s), receive W(1-f)/p * p(1+s) * (1-f) = W(1-f)^2(1+s).");
line("  Profit requires (1-f)^2 (1+s) > 1, therefore:");
line();
line("      s > 1/(1-f)^2 - 1");
line();
const sMin = 1 / (1 - M.hookFee) ** 2 - 1;
line(`  with f = ${M.hookFee}:   s > ${(sMin * 100).toFixed(2)}%`);
line();
line("  This is arithmetic, not judgement. A grid step below this loses money on");
line("  EVERY completed round trip no matter how the market moves.");
line();
// slippage at a realistic slice
const sliceWeth = (M.bookUsd / M.ethUsd) * 0.15;
const slip = sliceWeth / M.poolDepthWeth / 2;
line(`  Price impact on a ${(sliceWeth).toFixed(6)} WETH slice against ${M.poolDepthWeth} WETH`);
line(`  of depth: ~${(slip * 100).toFixed(4)}%  (negligible at this book size, material at 100x)`);
const sFloor = sMin + 2 * slip;
line(`  Break-even including impact: ${(sFloor * 100).toFixed(2)}%`);
line();
const STEP = 0.15;
line(`  [CHOICE] grid step = ${(STEP * 100).toFixed(0)}%, a ${((STEP / sFloor - 1) * 100).toFixed(0)}% margin over break-even.`);
const perRoundTrip = (1 - M.hookFee) ** 2 * (1 + STEP) - 1;
line(`  Consequence: each completed round trip nets ${(perRoundTrip * 100).toFixed(2)}% of the slice,`);
line(`  NOT ${(STEP * 100).toFixed(0)}%. The fee eats ${((STEP - perRoundTrip) / STEP * 100).toFixed(0)}% of the gross move.`);
line();

/* ================= 2. VOLATILITY FLOOR  [DERIVED FROM STEP] ================= */
line("2. VOLATILITY FLOOR  [DERIVED]");
rule();
line("  A grid only earns when price TRAVERSES a rung. For a driftless random walk the");
line("  expected time to move a fraction s scales as (s/sigma)^2. A round trip is two");
line("  traverses, so for R round trips per week (168h):");
line();
line("      hours per traverse = 168 / (2R)");
line("      sigma_hourly >= s / sqrt(168 / (2R)) = s * sqrt(2R/168)");
line();
line(`  ${"round trips/wk".padEnd(16)}${"hours/traverse".padStart(16)}${"required sigma_h".padStart(18)}`);
for (const R of [0.5, 1, 2, 4, 6, 10]) {
  const hrs = 168 / (2 * R);
  const need = STEP * Math.sqrt((2 * R) / 168);
  const flag = M.hourlyVolNow >= need ? "  <- today's 1.49% clears this" : "";
  line(`  ${String(R).padEnd(16)}${hrs.toFixed(1).padStart(16)}${(need * 100).toFixed(2).padStart(17)}%${flag}`);
}
line();
const R_TARGET = 4;
const volFloor = STEP * Math.sqrt((2 * R_TARGET) / 168);
line(`  [CHOICE] target R = ${R_TARGET} round trips/week  ->  vol floor = ${(volFloor * 100).toFixed(2)}%`);
line(`  The old hand-picked 4.00% implied R = ${(168 / 2 * (0.04 / STEP) ** 2).toFixed(1)}/week, which was never stated`);
line("  and never checked. Stating R makes the floor auditable.");
line();
line(`  At today's sigma_h of ${(M.hourlyVolNow * 100).toFixed(2)}%, one traverse takes`);
line(`  ~${((STEP / M.hourlyVolNow) ** 2).toFixed(0)} hours = ${(((STEP / M.hourlyVolNow) ** 2) / 24).toFixed(1)} days, i.e. ~${(168 / (2 * (STEP / M.hourlyVolNow) ** 2)).toFixed(2)} round trips/week.`);
line("  That is the real reason the desk is flat right now, expressed as a number");
line("  rather than as a threshold someone invented.");
line();

/* ============== 3. MINIMUM FILL SIZE  [DERIVED FROM GAS + STEP] ============= */
line("3. MINIMUM FILL SIZE  [DERIVED]");
rule();
line("  A fill is worth doing when its expected edge exceeds gas by a margin k:");
line();
line("      q * p * perRoundTrip > k * 2 * gasUsd        (two txs per round trip)");
line("      notional > k * 2 * gas / perRoundTrip");
line();
for (const k of [1, 3, 10]) {
  const min = (k * 2 * M.gasUsd) / perRoundTrip;
  line(`  k = ${String(k).padEnd(3)} -> minimum notional $${min.toFixed(2)}${k === 10 ? "   <- the desk uses k = 10" : ""}`);
}
const MIN_FILL = (10 * 2 * M.gasUsd) / perRoundTrip;
line();
line(`  [DERIVED] minFillUsd = $${MIN_FILL.toFixed(2)}`);
line(`  The old value was $0.33, derived as "10x gas" while ignoring that the edge is`);
line(`  ${(perRoundTrip * 100).toFixed(2)}%, not 100%. Correcting that raises the floor ${(MIN_FILL / 0.33).toFixed(1)}x.`);
line();

/* ========= 4. INVENTORY CAP  [DERIVED, Avellaneda-Stoikov inventory risk] === */
line("4. INVENTORY CAP  [DERIVED]");
rule();
line("  Avellaneda-Stoikov price inventory risk as gamma * sigma^2 * q. Rearranged as a");
line("  budget: if the desk will tolerate losing at most L of book to an adverse move of");
line("  Z standard deviations over a holding horizon H, then the RF fraction w satisfies");
line();
line("      w * Z * sigma_h * sqrt(H) <= L      ->      w <= L / (Z * sigma_h * sqrt(H))");
line();
const L_TOL = 0.10, Z = 2;
line(`  [CHOICE] tolerate L = ${(L_TOL * 100).toFixed(0)}% of book at Z = ${Z} sigma`);
line(`  ${"horizon (h)".padEnd(14)}${"sigma_h 1.5%".padStart(14)}${"sigma_h 3%".padStart(14)}${"sigma_h 6%".padStart(14)}`);
for (const H of [6, 24, 72, 168]) {
  const row = [0.015, 0.03, 0.06].map((sg) => {
    const w = L_TOL / (Z * sg * Math.sqrt(H));
    return `${Math.min(100, w * 100).toFixed(0)}%`.padStart(14);
  });
  line(`  ${String(H).padEnd(14)}${row.join("")}`);
}
const H_HOLD = 72;
const invCap = Math.min(1, L_TOL / (Z * Math.max(M.hourlyVolNow, 0.015) * Math.sqrt(H_HOLD)));
line();
line(`  At a ${H_HOLD}h holding horizon and today's vol: cap = ${(invCap * 100).toFixed(0)}%`);
line(`  [DERIVED] the cap is NOT a constant. It must fall as volatility rises; a fixed 60%`);
line("  is right at one volatility and wrong at every other. The desk now scales it.");
line();

/* ====================== 5. WHAT CANNOT BE DERIVED  [CHOICE] ================= */
line("5. WHAT REMAINS A JUDGEMENT  [CHOICE]");
rule();
line("  These have no defensible derivation and are stated as preferences:");
line();
line("   - maxDrawdown 15%       : risk appetite. Nothing computes it.");
line("   - maxAbsDrift7d 12%     : 'what counts as a trend'. A regime-detection problem");
line("                             that a 7-day drift only crudely approximates.");
line("   - minVolume24hWeth 25   : a liquidity comfort level, set above today's 13.7 so");
line("                             the desk cannot arm into a market this thin.");
line("   - minTrades24h 200      : same, for trade count.");
line("   - buyBlockedBelowDrift7d: the asymmetry threshold. Tuned on SYNTHETIC data,");
line("                             which is the weakest evidence in this file.");
line();
line("  The honest position: the first four sections are arithmetic from measured inputs");
line("  and would survive an argument. Section 5 would not. The desk is deliberately");
line("  conservative on all of them, so the failure mode is standing aside too often");
line("  rather than trading too much.");
line();

/* ============================= SUMMARY ==================================== */
line("SUMMARY: derived values vs the hand-picked ones they replace");
rule("=");
const rows = [
  ["grid step", "15%", `>= ${(sFloor * 100).toFixed(2)}% break-even`, "DERIVED floor, chosen margin"],
  ["edge per round trip", "n/a", `${(perRoundTrip * 100).toFixed(2)}%`, "DERIVED, was never stated"],
  ["vol floor", "4.00%", `${(volFloor * 100).toFixed(2)}%`, `DERIVED from R=${R_TARGET}/wk`],
  ["min fill", "$0.33", `$${MIN_FILL.toFixed(2)}`, "DERIVED, old one ignored the edge"],
  ["inventory cap", "60% fixed", `${(invCap * 100).toFixed(0)}% @ current vol`, "DERIVED, now vol-scaled"],
  ["max drawdown", "15%", "15%", "CHOICE, undefended"],
  ["drift gates", "various", "various", "CHOICE, tuned on synthetic data"],
];
line(`  ${"parameter".padEnd(22)}${"was".padStart(12)}${"now".padStart(26)}  basis`);
rule();
for (const [p, was, now, basis] of rows) {
  line(`  ${p.padEnd(22)}${was.padStart(12)}${now.padStart(26)}  ${basis}`);
}
rule("=");
line();
line("Nothing here is a forecast. It is the arithmetic of trading against a 10% toll.");

/* =============== 6. MINIMUM VIABLE BOOK  [DERIVED] ========================= */
line();
line("6. MINIMUM VIABLE BOOK SIZE  [DERIVED]  <- the finding that matters");
rule("=");
line("  A grid is two-sided. To SELL it needs RF; to BUY it needs WETH. Each fill must");
line("  clear the minimum economic notional, so BOTH sides must satisfy:");
line();
line("      side_value * sliceFrac >= minFillUsd");
line("      side_value >= minFillUsd / sliceFrac");
line();
const SLICE = 0.15;
line(`  ${"k".padEnd(5)}${"minFill".padStart(10)}${"per side @15% slice".padStart(22)}${"total balanced book".padStart(22)}`);
for (const k of [2, 3, 5, 10]) {
  const mf = (k * 2 * M.gasUsd) / perRoundTrip;
  const side = mf / SLICE;
  line(`  ${String(k).padEnd(5)}${("$" + mf.toFixed(2)).padStart(10)}${("$" + side.toFixed(0)).padStart(22)}${("$" + (side * 2).toFixed(0)).padStart(22)}`);
}
line();
const k5 = (5 * 2 * M.gasUsd) / perRoundTrip;
const sideNeeded = k5 / SLICE;
line(`  Hunt's actual book: $${M.bookUsd} total, but split 94% WETH / 6% RF:`);
line(`      WETH side  ~$79.27   slice $${(79.27 * SLICE).toFixed(2)}   ${79.27 * SLICE >= k5 ? "CLEARS" : "below"} the $${k5.toFixed(2)} floor`);
line(`      RF side    ~$ 4.94   slice $${(4.94 * SLICE).toFixed(2)}   ${4.94 * SLICE >= k5 ? "CLEARS" : "BELOW"} the $${k5.toFixed(2)} floor`);
line();
line("  So the desk can buy but can never economically sell, and a grid that cannot");
line("  sell never completes a round trip. THE BOOK IS TOO SMALL AND TOO LOPSIDED.");
line();
line(`  [DERIVED] minimum viable book, balanced: $${(sideNeeded * 2).toFixed(0)}  (k=5, 15% slice)`);
line(`  Hunt is at $${M.bookUsd}, i.e. ${((M.bookUsd / (sideNeeded * 2)) * 100).toFixed(0)}% of the way there, and on the wrong split.`);
line();
line("  Two ways out, both with a stated cost:");
line(`   1. Rebalance once: convert ~$${((sideNeeded - 4.94)).toFixed(0)} of WETH into RF, paying the 5% toll`);
line(`      (~$${((sideNeeded - 4.94) * 0.05).toFixed(2)}) to build the sell-side inventory a grid needs.`);
line(`   2. Pool more Friends. Protocol-wide idle rewards are roughly $30k, so ~${Math.ceil((sideNeeded * 2) / M.bookUsd)} members`);
line("      at Hunt's size clears it, and the split improves as RF rewards accrue.");
line();
line("  This is why the Bank is a BANK. One Friend's idle rewards cannot make a market.");
line("  Pooled, they can. That is the entire argument, and it is now a number.");
rule("=");
